"""Mission 05 browser regression: existing local servers, real data, isolated outage simulation."""
import argparse, csv, json, time
from pathlib import Path
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--base',default='http://127.0.0.1:5710')
args=parser.parse_args()
OUT=Path(__file__).resolve().parents[2]/'docs/mission05'
(OUT/'qa-downloads').mkdir(exist_ok=True)
checks=[]; errors=[]; console=[]; network=[]; started=time.time()
def check(name,ok,detail=None):
 checks.append({'name':name,'passed':bool(ok),'detail':detail})
 print(('PASS ' if ok else 'FAIL ')+name,flush=True)
 assert ok, f'{name}: {detail}'
def settled(page):
 page.wait_for_timeout(350)
 page.wait_for_function("""() => ![...document.querySelectorAll('main [role=status]')].some(e=>/Loading|Gathering|Updating|Calculating/.test(e.textContent))""",timeout=180000)
def fits(page):
 return page.evaluate('document.documentElement.scrollWidth<=innerWidth && document.querySelector("main").scrollWidth<=document.querySelector("main").clientWidth')
MAP="""() => {const el=document.querySelector('[role=application]');if(!el)return false;let f=el[Object.keys(el).find(k=>k.startsWith('__reactFiber'))];while(f){let h=f.memoizedState;while(h){const m=h.memoizedState?.current;if(m?.getStyle){window.__qaMap=m;return true}h=h.next}f=f.return}return false}"""
def attach(page):page.wait_for_function(MAP,timeout=60000)
def screenshot(page,name):page.screenshot(path=str(OUT/'after'/name),full_page=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless=True,args=['--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 ctx=browser.new_context(viewport={'width':1440,'height':900},accept_downloads=True)
 page=ctx.new_page();page.set_default_timeout(60000)
 page.on('pageerror',lambda e:errors.append(str(e)))
 page.on('console',lambda m:console.append(m.text) if m.type=='error' else None)
 page.on('response',lambda r:network.append({'status':r.status,'url':r.url.split('?')[0]}) if r.status>=400 else None)
 try:
  page.goto(args.base+'/?regiao=para',wait_until='domcontentloaded');settled(page)
  check('Home and shared Pará selection',page.get_by_role('heading',name='Latest satellite observations').count()==1 and page.get_by_label('Selected territory').input_value()=='para')
  page.wait_for_selector('[data-map-state=ready]');attach(page)
  page.wait_for_function("!window.__qaMap.isMoving() && window.__qaMap.areTilesLoaded() && window.__qaMap.queryRenderedFeatures({layers:['det-points']}).length>0",timeout=60000)
  check('Real MapLibre basemap, territorial layer and detection points rendered',page.evaluate("window.__qaMap.isStyleLoaded() && window.__qaMap.getLayer('boundary-line')!=null"))
  # Scan rendered municipal geometry, then perform an actual mouse click.
  pos=page.evaluate("""() => {const m=window.__qaMap,r=m.getCanvas().getBoundingClientRect();for(let y=35;y<r.height-70;y+=5)for(let x=30;x<r.width-35;x+=5){const f=m.queryRenderedFeatures([x,y],{layers:['mun-fill']});if(f[0]?.properties.id==='portel'&&[[0,0],[-4,0],[4,0],[0,-4],[0,4]].every(([dx,dy])=>m.queryRenderedFeatures([x+dx,y+dy],{layers:['mun-fill']})[0]?.properties.id==='portel')&&!m.queryRenderedFeatures([x,y],{layers:['det-points']}).length)return{x:r.x+x,y:r.y+y}}return null}""")
  check('Portel municipal polygon is selectable',bool(pos),pos)
  page.mouse.click(pos['x'],pos['y']);page.wait_for_function("document.querySelector('[aria-label=\"Selected territory\"]').value==='portel'");settled(page)
  check('Actual map click shares Portel through URL and selector','regiao=portel' in page.url)
  page.get_by_role('radio',name='7 days',exact=True).click();settled(page)
  page.get_by_role('radio',name='Night',exact=True).click();settled(page);page.wait_for_function("window.__qaMap.queryRenderedFeatures({layers:['det-points']}).length>0")
  check('Night filter uses real night observations',page.evaluate("window.__qaMap.queryRenderedFeatures({layers:['det-points']}).every(f=>f.properties.dn==='N')"))
  page.get_by_role('radio',name='All',exact=True).click();settled(page)
  page.locator('summary',has_text='Satellites').click()
  page.get_by_role('checkbox',name='NOAA-21 (VIIRS)',exact=False).uncheck();settled(page);page.wait_for_function("window.__qaMap.queryRenderedFeatures({layers:['det-points']}).length>0")
  check('Satellite filter removes NOAA-21 from rendered detections',page.evaluate("window.__qaMap.queryRenderedFeatures({layers:['det-points']}).every(f=>f.properties.p==='VIIRS_NOAA20_NRT')"))
  page.get_by_role('checkbox',name='NOAA-20 (VIIRS)',exact=False).uncheck();settled(page)
  check('No selected satellites produces an explicit empty state',page.get_by_role('heading',name='Select a satellite',exact=True).is_visible())
  page.get_by_role('checkbox',name='NOAA-20 (VIIRS)',exact=False).check();page.get_by_role('checkbox',name='NOAA-21 (VIIRS)',exact=False).check();page.locator('summary',has_text='Satellites').click();settled(page)
  # Click a real rendered observation on the geographic map.
  point=page.evaluate("""() => {const m=window.__qaMap,r=m.getCanvas().getBoundingClientRect();for(const f of m.queryRenderedFeatures({layers:['det-points']})){const p=m.project(f.geometry.coordinates);if(p.x>30&&p.x<r.width-35&&p.y>30&&p.y<r.height-70)return{x:r.x+p.x,y:r.y+p.y}}return null}""")
  check('Real observation available for map inspection',bool(point));page.mouse.click(point['x'],point['y'])
  page.get_by_role('heading',name='Thermal detection',exact=True).wait_for();page.get_by_text('Coordinates',exact=True).wait_for()
  detail=page.get_by_role('complementary',name='Observation details').inner_text()
  check('Clicked observation exposes satellite, sensor, UTC, coordinates, FRP, confidence and provenance',all(x in detail for x in ['Satellite','Sensor','Observation (UTC)','Coordinates','FRP','Confidence','Source: NASA FIRMS']))
  screenshot(page,'qa-map-observation.png');page.get_by_label('Close detection detail').click()
  page.locator('summary',has_text='Layers').click();page.get_by_role('checkbox',name='Geographic clusters').check();page.wait_for_timeout(1000)
  page.wait_for_function("window.__qaMap.queryRenderedFeatures({layers:['cluster-circles','cluster-single']}).length>0")
  check('Cluster layer activated with real features',page.evaluate("window.__qaMap.getLayoutProperty('cluster-circles','visibility')==='visible'"))
  page.get_by_role('checkbox',name='Individual detections').check();page.locator('summary',has_text='Layers').click()
  with page.expect_download() as dl:page.get_by_role('link',name='Export CSV',exact=True).click()
  path=OUT/'qa-downloads/recent-portel.csv';dl.value.save_as(path)
  raw=path.read_text();check('Recent CSV download retains original scientific columns','latitude' in raw and 'longitude' in raw and ('frp' in raw.lower()),raw.splitlines()[0][:200])
  page.get_by_role('link',name='Fire history',exact=True).click();page.get_by_role('tab',name='Experimental calendar',exact=True).click();settled(page)
  check('History shares Portel with its independent archive period',page.get_by_label('Selected territory').input_value()=='portel' and page.locator('.harmonized-calendar').count()==1)
  legend=page.get_by_label('Data origin legend').inner_text();check('Scientific calendar distinguishes all three origins',all(x in legend for x in ['Observed data','Experimentally converted data','Unavailable data']))
  page.locator('.calendar-cell.convertido_modis').first.click();check('Converted month displays empirical uncertainty',page.locator('.calendar-inspector').get_by_text('Empirical P10–P90 range').is_visible())
  check('Verified seasonal validation metrics and context',all(x in page.locator('.conversion-validation').inner_text() for x in ['15.9%','31.5%','25','2021–2025']))
  page.locator('summary',has_text='equivalent detection').click();check('Method retains uncalibrated-interval limitation','not a calibrated confidence or prediction interval' in page.locator('.method-disclosure').first.inner_text())
  with page.expect_download() as dl:page.get_by_role('link',name='Experimental series CSV',exact=True).click()
  dl.value.save_as(OUT/'qa-downloads/harmonized-portel.csv');check('Experimental CSV available',dl.value.failure() is None)
  page.get_by_role('tab',name='Observed records',exact=True).click();settled(page)
  check('Original sensor charts render',page.locator('.recharts-surface').count()>=3)
  screenshot(page,'qa-history-observed.png')
  page.get_by_role('tab',name='Methods & coverage',exact=True).click();settled(page)
  check('Historical method and provenance retained',page.get_by_role('heading',name='MODIS × VIIRS during overlapping years').count()==1)
  page.get_by_role('link',name='Territory analysis',exact=True).click();settled(page)
  for question in ['What is happening?','Is this activity unusual?','What environmental conditions are present?','Which areas need further investigation?','What evidence supports the analysis?']:page.get_by_role('heading',name=question,exact=True).wait_for()
  check('Territory answers five questions using shared selection',page.get_by_label('Selected territory').input_value()=='portel')
  check('Territory avoids a threat classification and retains caveats','not' in page.locator('main').inner_text().lower() and page.get_by_text('Scientific limitations',exact=True).count()==1)
  page.get_by_role('link',name='Open territory report',exact=True).click();page.get_by_role('heading',name='What was detected?',exact=True).wait_for(timeout=180000);settled(page)
  questions=['What was detected?','When was it observed?','Is this activity unusual?','What environmental conditions are present?','Which inhabited or protected territories are nearby?','What needs further verification?','What evidence and limitations support this analysis?']
  check('Existing report preserves all seven evidence questions',all(page.get_by_role('heading',name=q,exact=True).count()==1 for q in questions))
  with page.expect_download() as dl:page.get_by_role('button',name='Download JSON',exact=True).click()
  path=OUT/'qa-downloads/report-portel.json';dl.value.save_as(path);report=json.loads(path.read_text());check('Report JSON export preserves real provenance and region',report['region']['id']=='portel' and bool(report['brief']['recent']['products']))
  with page.expect_download() as dl:page.get_by_role('button',name='Proximity CSV',exact=False).click()
  dl.value.save_as(OUT/'qa-downloads/proximity-portel.csv');check('Proximity CSV export retained',dl.value.failure() is None)
  page.get_by_role('link',name='Environmental context',exact=True).click();settled(page)
  check('Environmental chart, units and reanalysis distinction',page.locator('.recharts-surface').count()>0 and 'not a measurement' in page.locator('main').inner_text())
  page.get_by_role('link',name='Evidence & exports',exact=True).click();settled(page)
  with page.expect_download() as dl:page.get_by_role('button',name='Download JSON manifest',exact=True).click()
  path=OUT/'qa-downloads/manifest-portel.json';dl.value.save_as(path);check('Evidence manifest downloadable',json.loads(path.read_text())['query']['region']=='portel')
  page.get_by_role('link',name='Current activity',exact=True).click();settled(page)
  check('Current period persists across modules',page.get_by_role('radio',name='7 days',exact=True).get_attribute('aria-checked')=='true')
  page.get_by_role('link',name='Fire history',exact=True).click();settled(page);page.get_by_label('Selected territory').select_option('para');settled(page);page.go_back();settled(page)
  check('Browser back restores shared territory from the previous module URL',page.get_by_label('Selected territory').input_value()=='portel')
  check('No runtime errors in complete desktop flow',not errors,errors)
  check('No unexpected HTTP or console errors',not network and not console,{'http':network,'console':console})
  # Mobile navigation and layout in a fresh context, including expanded controls.
  mob=browser.new_context(viewport={'width':390,'height':844});mp=mob.new_page();mp.set_default_timeout(60000)
  mp.goto(args.base+'/?regiao=para',wait_until='domcontentloaded');settled(mp)
  mp.get_by_label('Selected territory').select_option('portel');settled(mp)
  mp.locator('summary',has_text='Satellites').click();check('Mobile satellite popover fits viewport',fits(mp));mp.locator('summary',has_text='Satellites').click()
  mp.locator('summary',has_text='Layers').click();check('Mobile layer popover fits viewport',fits(mp));mp.locator('summary',has_text='Layers').click()
  for route,name in [('/','current'),('/historico','history'),('/territorio','territory'),('/ambiente','environment'),('/evidencias','evidence'),('/ficha/portel','report')]:
   mp.goto(args.base+route+'?regiao=portel',wait_until='domcontentloaded');settled(mp)
   check('Mobile layout without document overflow: '+name,fits(mp));screenshot(mp,'qa-mobile-'+name+'.png')
  mp.get_by_role('link',name='Current activity',exact=True).click();settled(mp);check('Mobile bottom navigation works',mp.get_by_role('heading',name='Latest satellite observations').is_visible())
  mob.close()
  # Only this isolated browser context intercepts the source response. Real backend untouched.
  outage=browser.new_context(viewport={'width':1440,'height':900});op=outage.new_page()
  outage.route('**/api/v1/detections?*',lambda route:route.fulfill(status=503,content_type='application/json',body=json.dumps({'error':{'code':'upstream_unavailable','message':'Simulated NASA FIRMS outage for browser testing.','source':'NASA FIRMS'}})))
  op.goto(args.base+'/?regiao=portel',wait_until='domcontentloaded');op.get_by_role('alert').wait_for(timeout=60000)
  check('API outage displays explanation and retry without fictitious records',op.get_by_role('button',name='Try again').is_visible() and op.locator('[data-feature-count="0"]').count()==1)
  screenshot(op,'qa-simulated-source-outage.png')
  outage.unroute('**/api/v1/detections?*');op.get_by_role('button',name='Try again').click();settled(op)
  op.wait_for_function("Number(document.querySelector('[data-feature-count]')?.dataset.featureCount)>0",timeout=60000)
  check('Retry recovers original source observations after outage',op.get_by_role('alert').count()==0)
  outage.close()
 except Exception as e:
  checks.append({'name':'Flow completed','passed':False,'detail':str(e)})
  print(str(e),flush=True)
  page.screenshot(path=str(OUT/'after/qa-failure.png'),full_page=True)
 finally:
  browser.close()
  (OUT/'test-results.json').write_text(json.dumps({'duration_seconds':round(time.time()-started,1),'checks':checks,'page_errors':errors,'console_errors':console,'http_errors':network},indent=2))
raise SystemExit(0 if all(c['passed'] for c in checks) else 1)
